CREATE TABLE public.journey_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), full_name text NOT NULL CHECK (char_length(full_name) BETWEEN 1 AND 80), stage text NOT NULL CHECK (stage IN ('discover','reset','rebuild','flourish','undecided')), destination text NOT NULL CHECK (destination IN ('phuket','china','usa','europe','undecided')), contact_method text NOT NULL CHECK (contact_method IN ('wechat','phone','email')), contact text NOT NULL CHECK (char_length(contact) BETWEEN 3 AND 120), preferred_date date, partner boolean NOT NULL DEFAULT false, preferred_language text NOT NULL DEFAULT 'zh' CHECK (preferred_language IN ('zh','en','es','ar')), focus text NOT NULL DEFAULT '' CHECK (char_length(focus) <= 1000), consent boolean NOT NULL CHECK (consent = true));
GRANT INSERT (full_name,stage,destination,contact_method,contact,preferred_date,partner,preferred_language,focus,consent) ON public.journey_applications TO anon, authenticated;
GRANT ALL ON public.journey_applications TO service_role;
ALTER TABLE public.journey_applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Visitors may submit private applications" ON public.journey_applications FOR INSERT TO anon, authenticated WITH CHECK (consent = true);